python - <<'E'
import uuid
p='Collection.cs'
s=open(p,encoding='utf-8-sig').read()
g=str(uuid.uuid4())
add='''
    [GrasshopperCollection("Bench", "Data")]
    public interface IMyDataPack : IBettaCollection
    {
        [GrasshopperMethod("Async Stats", "Mean and standard deviation of a list of numbers, computed asynchronously", Guid = "%s")]
        System.Threading.Tasks.Task<(double Mean, double StdDev)> AsyncStats(
            [GrasshopperParameter("Values")] System.Collections.Generic.List<double> values,
            System.Threading.CancellationToken cancellationToken);
    }

    public class MyDataPack : IMyDataPack
    {
        public System.Threading.Tasks.Task<(double Mean, double StdDev)> AsyncStats(
            System.Collections.Generic.List<double> values,
            System.Threading.CancellationToken cancellationToken)
        {
            return System.Threading.Tasks.Task.Run(() =>
            {
                if (values == null || values.Count == 0) return (0.0, 0.0);
                double sum = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    sum += v;
                }
                double mean = sum / values.Count;
                double sq = 0;
                foreach (var v in values)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    sq += (v - mean) * (v - mean);
                }
                return (mean, Math.Sqrt(sq / values.Count));
            }, cancellationToken);
        }
    }
}
''' % g
i=s.rstrip().rfind('}')
s=s[:i].rstrip()+'\n'+add
s=s.replace('using Betta.Interfaces;','using Betta.Interfaces;\nusing System;',1)
open(p,'w',encoding='utf-8').write(s)
E
dotnet build 2>&1 | tail -5
